// Nettoie et met en forme la demande envoyée par le site
const b = $input.first().json.body || {};

// Champ piège : seuls les robots le remplissent
if (b.website) throw new Error('Demande ignorée (anti-spam)');

const clean = (v, max = 500) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const d = {
  type: clean(b.typeLabel || b.type || 'Demande', 60),
  name: clean(b.name, 120),
  email: clean(b.email, 160),
  phone: clean(b.phone, 40),
  where: clean(b.where, 200),
  when: clean(b.when, 120) || 'Dès que possible',
  quantity: clean(b.quantity, 4),
  details: String(b.details ?? '').trim().slice(0, 2000),
  list: clean(b.list, 60) || 'Leclercq',
};
if (!d.name || !d.where) throw new Error('Demande incomplète : nom ou lieu manquant');
if (d.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(d.email)) d.email = '';

const quoi = d.type + (d.quantity ? ` × ${d.quantity}` : '');
const recu = new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris', weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' });

const subject = `[Demande] ${quoi} — ${d.name} (${d.where})`;
const text = [
  `Nouvelle demande reçue sur le site, ${recu}.`,
  '',
  `Demande   : ${quoi}`,
  `Qui       : ${d.name}`,
  `Où        : ${d.where}`,
  `Quand     : ${d.when}`,
  `Téléphone : ${d.phone || '—'}`,
  `E-mail    : ${d.email || '—'}`,
  '',
  d.details ? `Précisions :\n${d.details}` : 'Pas de précisions.',
  '',
  'Répondez directement à ce mail pour écrire à l\'étudiant.',
].join('\n');

const confirmSubject = `Liste ${d.list} — on a bien reçu votre demande`;
const confirmText = [
  `Bonjour ${d.name.split(' ')[0]},`,
  '',
  `Votre demande « ${quoi} » est bien arrivée.`,
  `Lieu : ${d.where} · Quand : ${d.when}`,
  '',
  'Un membre de la liste s\'en occupe et revient vers vous très vite.',
  '',
  `La liste ${d.list}`,
].join('\n');

return [{ json: { ...d, subject, text, confirmSubject, confirmText } }];
